from PIL import Image
im=Image.open('/home/robot/captures/overview_004.jpg').convert('RGB')
w=100; h=int(im.height/im.width*w*0.55)
small=im.resize((w,h))
pix=small.load()
for y in range(h):
    line=''
    for x in range(w):
        r,g,b=pix[x,y]
        # classify
        if r>120 and g>70 and b<90 and (r-b)>50:
            c='Y'
        elif r>160 and g>160 and b>160:
            c='#'
        elif r<60 and g<60 and b<60:
            c=' '
        elif r>g and r>b and (r-b)>40 and (r-g)<80:
            c='o'  # orange/brown
        else:
            c='.'
        line+=c
    print(line)
